import{_ as o,o as r,c as t,ag as n}from"./chunks/framework.em2JOrjF.js";const d=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/glossary.md","filePath":"guide/glossary.md"}'),a={name:"guide/glossary.md"};function s(i,e,g,h,l,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Terms you&#39;ll encounter when using VERA, explained for day-to-day use.</p><hr><p><strong>Billable / non-billable</strong> Whether the time you&#39;re logging generates revenue for the business. Most client work is billable. Internal projects (training, admin, R&amp;D) are not. VERA knows which is which — you don&#39;t need to set this yourself.</p><hr><p><strong>Briefing</strong> The message VERA sends each weekday morning. It summarises your recent hours, your work plan for the week, and (for managers and owners) the health of your portfolio. See <a href="./morning-briefing.html">The morning briefing</a>.</p><hr><p><strong>Burn rate</strong> How quickly a project&#39;s hours are being used relative to what was planned. A project burning hours faster than expected will run out of budget before the deadline. Managers and owners see burn rate in their morning briefing and in retainer summaries.</p><hr><p><strong>Envelope</strong> A work plan your manager has assigned to you on a specific project and task type. It defines how many hours you&#39;re expected to contribute. Your envelope shows up in your morning briefing as Plan / Logged / Remaining.</p><p>Envelopes are planning tools — they don&#39;t restrict you from logging time. You can log to any active project whether or not you have an envelope for it.</p><hr><p><strong>Leave</strong> An extended absence (parental, compassionate, unpaid, and so on). Requested through VERA and approved by a manager, the same way as <a href="./time-off.html">time off</a>.</p><hr><p><strong>Log / logging</strong> The act of recording your hours in VERA. &quot;Log 3 hours on Nike, design&quot; is all it takes. See <a href="./logging-time.html">Logging time</a>.</p><hr><p><strong>Morning briefing</strong> See <em>Briefing</em>.</p><hr><p><strong>Period</strong> A single billing cycle within a retainer — typically one month. Each period has its own hours budget and contract value. When a period closes, a new one opens. You log time against the current period, not the retainer as a whole.</p><hr><p><strong>Project</strong> The thing you&#39;re working on. Every hour you log goes to a project. Projects belong to clients (or to your own company, for internal work). Your manager or owner sets up projects — you just log to them.</p><hr><p><strong>PTO</strong> Paid time off. Requested through VERA and approved by your manager before being recorded. You can&#39;t log PTO directly — it has to go through the approval process. See <a href="./time-off.html">Time off</a>.</p><hr><p><strong>Retainer</strong> An ongoing client engagement with a fixed fee per period (usually monthly). The client pays a set amount; the team delivers a set number of hours. VERA tracks how much of the current period has been used. See <a href="./projects.html">Projects and tasks</a> for more on retainers.</p><hr><p><strong>Sick day</strong> A day off due to illness. Unlike PTO, sick days don&#39;t require a formal request — your manager logs them on your behalf. See <a href="./time-off.html">Time off</a>.</p><hr><p><strong>Sprint</strong> A time-boxed delivery unit in an Agile project. Like a retainer period, each sprint has its own hours and contract value. When one sprint closes, the next one opens.</p><hr><p><strong>Task</strong> The type of work you&#39;re doing within a project — Design, Development, Strategy, Admin, and so on. Each project has a specific set of tasks enabled for it. If you have a single task planned on a project, VERA applies it automatically when you log time. If you have multiple, they&#39;ll ask. To see which tasks are available: &quot;What tasks are on the Nike project?&quot;</p><hr><p><strong>Team member</strong> The default role in VERA. Team members log their own time and see their own data. See <a href="./roles.html">Your role in VERA</a>.</p><hr><p><strong>Time entry</strong> A single record of work: a date, a project, a number of hours, and usually a task. Created when you log time. Can be edited or deleted if something&#39;s wrong.</p><hr><p><strong>Work plan</strong> See <em>Envelope</em>.</p>',37)])])}const m=o(a,[["render",s]]);export{d as __pageData,m as default};
